{
  "pains": [
    {
      "id": "pain:surprise-observability-bill",
      "statement": "The Datadog bill started reasonable, then one change - sidecars, LLM logs, more hosts - doubled it and now we're scrambling to refactor around the pricing.",
      "element": "b2b:functional:cost_reduction",
      "shape": {
        "surface": "A monthly bill that jumps with no warning because of how hosts, containers and logs are counted.",
        "operational": "Engineers refactor or drop architecture choices (a service mesh, verbose logging) to avoid the bill, or run a migration to an open-source stack.",
        "personal": null,
        "personal_note": "The quotes stop at budget and refactor work; none says what the surprise bill cost the person who owned it. Looked through the HN 'Datadog $65M customer' thread and the LLM-logs Ask HN."
      },
      "workflow": "At Datadog renewal or month-end invoice review, after a Kubernetes sidecar rollout (Istio/Linkerd) or after LLM logs start flowing into the same log pipeline as APM.",
      "type": "felt",
      "confidence": "high",
      "priority": 1,
      "felt_evidence": {
        "kind": "switching",
        "what": "Small teams report leaving Datadog over cost: one moved to an open-source Grafana stack, another cut monitoring and alerting costs by 90% after switching.",
        "cites": ["src:5", "src:6"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "A service mesh rollout where each sidecar container is billed as an extra host.", "cites": ["src:2"]},
        {"event": "Starting to log LLM calls, which are far larger than existing APM logs.", "cites": ["src:3"]}
      ],
      "who_feels": ["economic_buyer", "end_user"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {"situation": "venting", "verbatim": "and then grows to a non-trivial percent of saas budget, and then theres a scramble to refactor.", "cites": ["src:3"]},
            {"situation": "when_looking", "verbatim": "Trying to get ahead of that as the LLM logs are MUCH larger that my APM logs.", "cites": ["src:3"]}
          ],
          "costs_them": "A growing share of the SaaS budget and an unplanned refactor project.",
          "fears": "That the next data source added makes the bill grow again before anyone notices.",
          "dream_outcome": "Spend that stays predictable as log and host volume grows."
        },
        "end_user": {
          "says": [
            {"situation": "when_it_bites", "verbatim": "datadog apparently bills sidecar containers as additional hosts so using sidecar proxy would have doubled our datadog bill.", "cites": ["src:2"]},
            {"situation": "venting", "verbatim": "If I were more cynical I would say the pricing model is designed to be confusing so customers spend more than they need,", "cites": ["src:1"]}
          ],
          "costs_them": "Architecture options they can't use and bills they can't predict from the pricing page.",
          "fears": "No source shows a fear beyond the next surprising bill; the quotes stop at cost and confusion.",
          "dream_outcome": "Pick the architecture on its merits, not on how the vendor counts hosts."
        }
      },
      "relief": {
        "line": "Bill cut. Same monitoring, a fraction of the cost.",
        "says": [
          {"role": "economic_buyer", "verbatim": "By switching to Better Stack, we were able to cut our monitoring and alerting costs by 90%,", "cites": ["src:6"]},
          {"role": "end_user", "verbatim": "more flexible, complete and manageable than yet another SaaS.", "cites": ["src:5"]}
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Cost off the agenda. Observability stops being a budget line anyone argues about.",
        "says": [],
        "gap": "Read the switch stories in the HN 'Datadog $65M customer' thread; they describe the saving, none describes a year later. G2 and TrustRadius 4-5 star reviews were blocked (403)."
      },
      "segments": ["seg:startup", "seg:platform"],
      "feature_ref": null,
      "feature_note": "Pricing model, not a product feature: what kills it is Grafana's open-source stack or usage-based Grafana Cloud pricing that does not count sidecars as hosts. Needs a pricing claim the company artifact does not record.",
      "cites": ["src:1", "src:2", "src:3"]
    },
    {
      "id": "pain:self-hosting-eats-our-time",
      "statement": "Running Prometheus, Grafana and Loki ourselves is cheap on paper, but now we need monitoring on our monitoring and it eats a real chunk of an engineer's week.",
      "element": "b2b:ease_of_doing_business:reduced_effort",
      "shape": {
        "surface": "The self-hosted stack goes down or needs tuning, and setup takes nights of config and dashboard tweaking.",
        "operational": "An engineer maintains the stack, adds features, and builds a second layer of monitoring to watch the first.",
        "personal": "The setup work is put off for years or swallows nights of re-learning PromQL instead of the work they were hired for.",
        "personal_note": "From one practitioner (src:10) on setup at home plus src:8 on attention at work."
      },
      "workflow": "During a Datadog-to-Prometheus/Grafana migration: spinning up the VM, configuring Prometheus, Grafana and collectors, then tweaking dashboards and writing PromQL, and keeping it all up afterwards.",
      "type": "felt",
      "confidence": "medium",
      "priority": 2,
      "felt_evidence": {
        "kind": "complaining",
        "what": "In an August 2026 HN thread, a team says it tried to replace Datadog with OpenTelemetry and was crushed by the complexity.",
        "cites": ["src:9"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "A decision to move off Datadog to self-hosted Prometheus/Grafana.", "cites": ["src:7"]}
      ],
      "who_feels": ["end_user", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            {"situation": "venting", "verbatim": "We are moving from Datadog to Prometheus/Grafana and it", "cites": ["src:7"]},
            {"situation": "when_it_bites", "verbatim": "Our team tried to set up open telemetry to replace Datadog and got totally crushed in complexity.", "cites": ["src:9"]},
            {"situation": "venting", "verbatim": "and then spend a night or three tweaking dashboards and re-learning promql or whatever.", "cites": ["src:10"]}
          ],
          "costs_them": "Nights of setup and the ongoing upkeep of a stack that also needs its own monitoring.",
          "fears": "That the stack fails when nobody is watching it.",
          "dream_outcome": "The open-source stack without having to be its operator."
        },
        "economic_buyer": {
          "says": [
            {"situation": "venting", "verbatim": "this would also consume a noticeable fraction of my time,", "cites": ["src:8"]},
            {"situation": "to_their_boss", "verbatim": "It is much easier to find $100,000 a year of budget than it is to find an additional $50,000", "cites": ["src:8"]}
          ],
          "costs_them": "Skilled developer time, which is harder to find than budget.",
          "fears": "Unpredictable outages of the homegrown stack pulling attention from higher-value work.",
          "dream_outcome": "Pay for it and spend scarce attention elsewhere."
        }
      },
      "relief": {
        "line": "Done in an afternoon. The setup that sat on the todo list for years is finished.",
        "says": [
          {"role": "end_user", "verbatim": "Got it done in a couple hours with openclaw.", "cites": ["src:10"]}
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Nobody's side job. The stack runs without an engineer owning it.",
        "says": [],
        "gap": "Searched HN for teams a year into a managed or self-hosted stack; found migration stories and setup complaints, no after-year account. Reddit blocked."
      },
      "segments": ["seg:startup"],
      "feature_ref": "feat:metrics",
      "feature_note": "Grafana Cloud's managed Mimir, Loki and Tempo remove the operating work while keeping the open-source stack.",
      "cites": ["src:7", "src:8", "src:9"]
    },
    {
      "id": "pain:logs-metrics-traces-dont-connect",
      "statement": "Grafana's easy for a basic install, but once you try to wire logs, metrics and traces together, each needs its own query language and it gets out of hand fast.",
      "element": "b2b:ease_of_doing_business:integration",
      "shape": {
        "surface": "Panels that support one query language and not another; logs, metrics and traces that don't link up.",
        "operational": "Engineers learn PromQL, LogQL and TraceQL separately and hand-wire the connections, or the company pays for Datadog to avoid it.",
        "personal": null,
        "personal_note": "Quotes describe confusion and complexity, not what it cost the person. Looked through the 'OTel isn't going well' HN thread."
      },
      "workflow": "Self-hosted Grafana with Loki, Prometheus and Tempo behind an Alloy/OTel collector, at the step of jumping from a suspicious graph to the matching logs and trace.",
      "type": "felt",
      "confidence": "medium",
      "priority": 3,
      "felt_evidence": {
        "kind": "paying",
        "what": "A practitioner says their employer chose Datadog despite the cost because one query language beats a different one per data source.",
        "cites": ["src:11"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "Adding OpenTelemetry to a self-hosted Grafana stack.", "cites": ["src:12"]}
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {"situation": "venting", "verbatim": "The biggest challenge I have is that each data source needs it", "cites": ["src:11"]},
            {"situation": "venting", "verbatim": "once you start connecting stuff it starts adding complexity not ease.", "cites": ["src:12"]},
            {"situation": "when_looking", "verbatim": "I wish there was a way I could just annotate my code base once,", "cites": ["src:13"]}
          ],
          "costs_them": "Time learning three query languages and wiring signals that should already connect.",
          "fears": "No source shows the fear; the quotes stop at complexity.",
          "dream_outcome": "One click from a suspicious graph to the trace behind it."
        }
      },
      "relief": {
        "line": "It works for me. The open-source stack covers personal and client work.",
        "says": [
          {"role": "end_user", "verbatim": "for all of my personal and consulting jobs, OSS LGTM/P works good for me.", "cites": ["src:11"]}
        ],
        "gap": null
      },
      "euphoria": {
        "line": "One place to ask. Any signal, one question.",
        "says": [],
        "gap": "No buyer in the HN threads read describes the after-state of unified querying. Review sites blocked."
      },
      "segments": ["seg:startup"],
      "feature_ref": "feat:traces",
      "feature_note": "Grafana's pitch is linked metrics, logs and traces; buyers say the separate query languages are where it breaks.",
      "cites": ["src:11", "src:12", "src:13"]
    },
    {
      "id": "pain:on-call-wrecks-sleep",
      "statement": "When I'm on call I sleep in another room and still can't fall asleep, waiting for an alert to go off.",
      "element": "b2b:individual:reduced_anxiety",
      "shape": {
        "surface": "A pager that could go off at any hour during a week-long 24/7 rotation.",
        "operational": "Engineers turn alerts down to the bare minimum so only full outages page them.",
        "personal": "Sleeping in a separate room from a partner, trouble falling asleep, no drinking for a week."
      },
      "workflow": "A week-long 24/7 on-call rotation shared by six engineers, overnight, with pages routed from the monitoring stack to the phone.",
      "type": "felt",
      "confidence": "medium",
      "priority": 4,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Engineers on HN describe on-call as disrupting sleep and family; dated July 2022, so older than the other pains.",
        "cites": ["src:14", "src:15"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "Being added to a week-long 24/7 on-call rotation for the first time.", "cites": ["src:14"]}
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {"situation": "when_it_bites", "verbatim": "When on-call, I sleep in a separate room from my wife so that her sleep is not disrupted.", "cites": ["src:14"]},
            {"situation": "venting", "verbatim": "I agree that being on call is disruptive and I always had trouble sleeping just in case I missed a call.", "cites": ["src:15"]},
            {"situation": "venting", "verbatim": "I also have a hard time falling asleep knowing that an alert could go off at any time.", "cites": ["src:14"]}
          ],
          "costs_them": "Sleep and family time for every on-call week.",
          "fears": "Missing a page.",
          "dream_outcome": "Only get woken when the site is actually down."
        }
      },
      "relief": {
        "line": "Paged only for real outages. Everything else waits for morning.",
        "says": [
          {"role": "end_user", "verbatim": "just turn down the alerts to the bare minimum.", "cites": ["src:16"]}
        ],
        "gap": null
      },
      "euphoria": {
        "line": "On-call week like any other. Same bed, same sleep.",
        "says": [],
        "gap": "The only after-state found is a workaround (turning alerts down). Reddit and review sites blocked."
      },
      "segments": ["seg:platform"],
      "feature_ref": "feat:irm",
      "feature_note": "Grafana IRM covers scheduling and routing; whether it reduces night pages is untested here.",
      "cites": ["src:14", "src:15"]
    }
  ],
  "awareness": {
    "default": {
      "level": "solution",
      "rationale": "Buyers compare named tools (Datadog, Grafana, OpenTelemetry, Dash0, Better Stack) and recommend one over another.",
      "cites": ["src:1", "src:11"]
    }
  },
  "stats": [],
  "keywords": [
    "datadog bill too high",
    "datadog sidecar billed as host",
    "open source datadog alternative",
    "self hosted grafana loki tempo",
    "monitoring your monitoring",
    "re-learning promql",
    "connect logs metrics traces grafana",
    "on call can't sleep"
  ],
  "questions": [
    {"id": "q:pains-first-call", "question": "On the last ten first calls, which did buyers raise first: the Datadog bill, running the stack themselves, or linking logs, metrics and traces?", "why": "Priority order here is based on public threads, not Grafana's own buyers.", "would_change": "pains[].priority"},
    {"id": "q:pains-wrong-subsystem", "question": "Do customers say incidents drag on for days because the first error points at the wrong subsystem while logs and metrics look fine?", "why": "Found once (src:17); one source is not a pain row, and it would be the pain the AI investigations feature kills.", "would_change": "pains[]"},
    {"id": "q:pains-enterprise", "question": "What do Fortune 500 buyers say hurts? No public enterprise voice was found.", "why": "seg:enterprise has no source, so no pain lists it.", "would_change": "pains[].segments"},
    {"id": "q:pains-bill-personal", "question": "When the observability bill surprised a customer, what did it cost the person who owned it?", "why": "The personal rung of the top pain is null.", "would_change": "pains[].shape.personal"}
  ],
  "sources": [
    {"id": "src:1", "url": "https://news.ycombinator.com/item?id=44433840", "title": "Comment by ljm on 'Datadog's $65M/year customer mystery solved'", "venue": "Hacker News", "speaker": "practitioner", "published": "2025-07", "pulled": "2026-10-12", "verbatim": "I used to be quite fond of Datadog but after one or two completely surprising bills If I were more cynical I would say the pricing model is designed to be confusing so customers spend more than they need, and this is only made worse by the extreme breadth of the platform now."},
    {"id": "src:2", "url": "https://news.ycombinator.com/item?id=45438010", "title": "Comment by pm90 on service meshes", "venue": "Hacker News", "speaker": "practitioner", "published": "2025-10-01", "pulled": "2026-10-12", "verbatim": "datadog apparently bills sidecar containers as additional hosts so using sidecar proxy would have doubled our datadog bill."},
    {"id": "src:3", "url": "https://news.ycombinator.com/item?id=46558282", "title": "Comment by platypii on 'Ask HN: Where are you keeping your LLM logs?'", "venue": "Hacker News", "speaker": "buyer", "published": "2026-01-09", "pulled": "2026-10-12", "verbatim": "and then grows to a non-trivial percent of saas budget, and then theres a scramble to refactor. Trying to get ahead of that as the LLM logs are MUCH larger that my APM logs."},
    {"id": "src:5", "url": "https://news.ycombinator.com/item?id=44427323", "title": "Comment by delichon on 'Datadog's $65M/year customer mystery solved'", "venue": "Hacker News", "speaker": "buyer", "published": "2025-06-30", "pulled": "2026-10-12", "verbatim": "We recently did the same, and our Datadog bill was only five figures. but more flexible, complete and manageable than yet another SaaS."},
    {"id": "src:6", "url": "https://news.ycombinator.com/item?id=44429123", "title": "Comment by wenbin (Listen Notes) on 'Datadog's $65M/year customer mystery solved'", "venue": "Hacker News", "speaker": "buyer", "published": "2025-06", "pulled": "2026-10-12", "verbatim": "replacing both Datadog and PagerDuty, By switching to Better Stack, we were able to cut our monitoring and alerting costs by 90%, with basically the same things that we used from Datadog previously."},
    {"id": "src:7", "url": "https://news.ycombinator.com/item?id=44428684", "title": "Comment by secondcoming on 'Datadog's $65M/year customer mystery solved'", "venue": "Hacker News", "speaker": "practitioner", "published": "2025-06", "pulled": "2026-10-12", "verbatim": "We are moving from Datadog to Prometheus/Grafana and it"},
    {"id": "src:8", "url": "https://news.ycombinator.com/item?id=44435174", "title": "Comment by xp84 on 'Datadog's $65M/year customer mystery solved'", "venue": "Hacker News", "speaker": "buyer", "published": "2025-07-01", "pulled": "2026-10-12", "verbatim": "this would also consume a noticeable fraction of my time, both in predictable ways (maintenance, feature adds that I decide I need), It is much easier to find $100,000 a year of budget than it is to find an additional $50,000"},
    {"id": "src:9", "url": "https://news.ycombinator.com/item?id=49401661", "title": "Comment by czhu12 on 'OTel isn't going well'", "venue": "Hacker News", "speaker": "practitioner", "published": "2026-08", "pulled": "2026-10-12", "verbatim": "Our team tried to set up open telemetry to replace Datadog and got totally crushed in complexity."},
    {"id": "src:10", "url": "https://news.ycombinator.com/item?id=47482692", "title": "Comment by phil21 on 'OpenClaw is a security nightmare dressed up as a daydream'", "venue": "Hacker News", "speaker": "practitioner", "published": "2026-03-22", "pulled": "2026-10-12", "verbatim": "but god what a pain in the ass to spin up a VM, configure Prometheus, configure grafana, and then spend a night or three tweaking dashboards and re-learning promql or whatever. I just end up never doing it. Got it done in a couple hours with openclaw."},
    {"id": "src:11", "url": "https://news.ycombinator.com/item?id=49401802", "title": "Comment by losingthefight on 'OTel isn't going well'", "venue": "Hacker News", "speaker": "practitioner", "published": "2026-08", "pulled": "2026-10-12", "verbatim": "I run OSS Grafana with Loki, Prometheus, and Tempo. The biggest challenge I have is that each data source needs it We are also looking at Dash0 but for all of my personal and consulting jobs, OSS LGTM/P works good for me."},
    {"id": "src:12", "url": "https://news.ycombinator.com/item?id=49404850", "title": "Comment by Havoc on 'OTel isn't going well'", "venue": "Hacker News", "speaker": "practitioner", "published": "2026-08", "pulled": "2026-10-12", "verbatim": "Grafana is fine to get to a selfhosted basic install. modular in a way that seems like a win but once you start connecting stuff it starts adding complexity not ease."},
    {"id": "src:13", "url": "https://news.ycombinator.com/item?id=49396130", "title": "Comment by EdSchouten on 'OTel isn't going well'", "venue": "Hacker News", "speaker": "practitioner", "published": "2026-08", "pulled": "2026-10-12", "verbatim": "What always puzzles me about OpenTelemetry is that tracing, metrics and logs are all designed independently. I wish there was a way I could just annotate my code base once,"},
    {"id": "src:14", "url": "https://news.ycombinator.com/item?id=32038044", "title": "Ask HN: Are you on-call after business hours? (cad1)", "venue": "Hacker News", "speaker": "practitioner", "published": "2022-07-09", "pulled": "2026-10-12", "verbatim": "I was notified I would have to start taking a week long 24/7 on-call rotation with 5 other team members. I find being on-call invasive and disruptive, not only for me but also my family. When on-call, I sleep in a separate room from my wife so that her sleep is not disrupted. I also have a hard time falling asleep knowing that an alert could go off at any time."},
    {"id": "src:15", "url": "https://news.ycombinator.com/item?id=32038198", "title": "Reply by NickRandom on 'Ask HN: Are you on-call after business hours?'", "venue": "Hacker News", "speaker": "practitioner", "published": "2022-07", "pulled": "2026-10-12", "verbatim": "I agree that being on call is disruptive and I always had trouble sleeping just in case I missed a call."},
    {"id": "src:16", "url": "https://news.ycombinator.com/item?id=32038754", "title": "Reply by icedchai on 'Ask HN: Are you on-call after business hours?'", "venue": "Hacker News", "speaker": "practitioner", "published": "2022-07", "pulled": "2026-10-12", "verbatim": "just turn down the alerts to the bare minimum."},
    {"id": "src:17", "url": "https://news.ycombinator.com/item?id=49192345", "title": "Comment by IgorVoytyuk on 'Launch HN: HyperProbe'", "venue": "Hacker News", "speaker": "practitioner", "published": "2026-08", "pulled": "2026-10-12", "verbatim": "In all three the logs were complete and the metrics were green.", "unused": "Single source for a wrong-diagnosis pain; held as q:pains-wrong-subsystem."}
